<script setup lang="ts">
import { ArrowLeft, ArrowUpRight, Download, ShieldAlert, ShieldCheck } from 'lucide-vue-next'
definePageMeta({ layout: 'app' })
const route = useRoute(); const api = useApi()
const { data: report } = await useAsyncData(`report-${route.params.id}`, () => api.request<any>(`/portal/reports/${route.params.id}`).catch(() => null))
if (!report.value) throw createError({ statusCode: 404, statusMessage: 'Report not found' })
const asset = computed(() => report.value?.asset)
const view = ref<'3d' | '2d'>('3d')
const { data: comparison } = await useAsyncData(`comparison-${route.params.id}`, () => api.request<any>(`/portal/reports/${route.params.id}/comparison`).catch(() => null))
async function print() { try { await api.download(`/portal/reports/${route.params.id}/pdf`, `vomtek-${report.value.ref}.pdf`) } catch { window.print() } }
</script>
<template>
  <div v-if="report">
    <div class="mb-5 flex flex-wrap items-center justify-between gap-3"><NuxtLink to="/app/inspections" class="inline-flex items-center gap-2 font-mono text-[9px] uppercase tracking-[.08em] text-ink/40 hover:text-ink"><ArrowLeft :size="12" /> Inspections</NuxtLink><div class="flex gap-2"><button class="btn btn-outline !min-h-8 !px-3 !text-[9px]" @click="print"><Download :size="12" /> Export report</button><NuxtLink to="/contact" class="btn btn-dark !min-h-8 !px-3 !text-[9px]">Ask an engineer <ArrowUpRight :size="12" /></NuxtLink></div></div>
    <div class="rounded-2xl border border-ink/12 bg-bone">
      <div class="flex flex-col gap-4 border-b border-ink/10 p-5 md:flex-row md:items-start md:justify-between md:p-7"><div><p class="label-mono text-signal-deep">Integrity report · {{ report.ref }}</p><h1 class="type-product-hero mt-2">{{ asset?.name }}</h1><p class="mt-2 font-mono text-[9.5px] uppercase tracking-[.06em] text-ink/40">{{ asset?.location }} · {{ asset?.diameterMm }} mm OD · {{ asset?.lengthKm }} km · MAOP {{ asset?.maopKpa }} kPa</p></div><div class="flex items-center gap-3"><StatusPill :status="report.risk" /><span class="font-mono text-[9px] text-ink/40">{{ shortDate(report.createdAt) }}</span></div></div>
      <div class="grid gap-0 md:grid-cols-4 md:divide-x md:divide-ink/10"><div v-for="(m, i) in [{l:'Deepest metal loss',v:`${report.maxDepthPct}%`,n:'of nominal wall'},{l:'Corrosion rate',v:`${report.cgr} mm/y`,n:'against prior run'},{l:'Safe pressure',v:`${(report.safePressureKpa/1000).toFixed(1)} MPa`,n:`MAOP ${(asset?.maopKpa/1000).toFixed(1)} MPa`},{l:'Remaining life',v:`${report.remainingLifeYears} y`,n:'at current CGR'}]" :key="m.l" class="p-5"><p class="font-mono text-[8px] uppercase tracking-[.08em] text-ink/35">{{ m.l }}</p><p class="mt-2 font-display text-[32px] leading-none tracking-[-.03em]" :class="i === 0 && report.maxDepthPct > 50 ? 'text-signal-deep' : ''">{{ m.v }}</p><p class="mt-1 text-[10px] text-ink/40">{{ m.n }}</p></div></div>
      <div class="border-t border-ink/10 p-5 md:p-7"><div class="flex items-center gap-2"><ShieldAlert :size="15" class="text-signal" /><p class="font-mono text-[8.5px] uppercase tracking-[.08em] text-ink/40">Engineering summary</p></div><p class="mt-3 max-w-3xl text-[15px] leading-relaxed text-ink/70">{{ report.summary }}</p></div>
    </div>
    <div class="mt-5 grid gap-5 xl:grid-cols-12">
      <div class="xl:col-span-8">
        <div class="overflow-hidden rounded-xl border border-ink/12 bg-ink p-3 text-bone"><div class="flex items-center justify-between px-2 pb-2"><p class="font-mono text-[8px] uppercase tracking-[.1em] text-bone/40">{{ view === "3d" ? "3D digital twin" : "Anomaly depth profile" }}</p><div class="flex items-center gap-2"><div class="flex gap-3 font-mono text-[8px] uppercase text-bone/40"><span class="flex items-center gap-1"><i class="size-1.5 rounded-full bg-mint" />Low</span><span class="flex items-center gap-1"><i class="size-1.5 rounded-full bg-[#f6c453]" />Medium</span><span class="flex items-center gap-1"><i class="size-1.5 rounded-full bg-signal" />High</span></div><div class="ml-2 flex rounded-full border border-bone/15 p-0.5"><button class="rounded-full px-2 py-1 font-mono text-[7.5px] uppercase" :class="view==='3d'?'bg-bone text-ink':'text-bone/45'" @click="view='3d'">3D</button><button class="rounded-full px-2 py-1 font-mono text-[7.5px] uppercase" :class="view==='2d'?'bg-bone text-ink':'text-bone/45'" @click="view='2d'">2D</button></div></div></div><ClientOnly><ReportTwin v-if="view==='3d'" :anomalies="report.anomalies" :length-km="asset?.lengthKm || 40" :height="320" /><AnomalyCanvas v-else :anomalies="report.anomalies" :length-km="asset?.lengthKm || 40" :height="300" /></ClientOnly></div>
        <div class="mt-4 overflow-hidden rounded-xl border border-ink/12 bg-bone"><div class="border-b border-ink/10 px-4 py-3"><p class="font-display text-[18px]">Anomaly register</p></div><div class="max-h-[460px] overflow-auto scrollbar-thin"><table class="w-full text-left text-[11px]"><thead class="sticky top-0 bg-bone-2"><tr class="font-mono text-[8px] uppercase tracking-[.06em] text-ink/35"><th class="px-3 py-2">ID</th><th class="px-3 py-2">Distance</th><th class="px-3 py-2">Type</th><th class="px-3 py-2">Depth</th><th class="px-3 py-2">Life</th><th class="px-3 py-2">B31G</th></tr></thead><tbody><tr v-for="a in report.anomalies" :key="a.id" class="border-t border-ink/10"><td class="px-3 py-2.5 font-mono text-[9px]">{{ a.id }}</td><td class="px-3 py-2.5">{{ (a.distanceM/1000).toFixed(2) }} km</td><td class="px-3 py-2.5">{{ a.type }}</td><td class="px-3 py-2.5"><span :class="a.severity === 'critical' ? 'text-signal-deep font-semibold' : a.severity === 'high' ? 'text-[#a46800]' : ''">{{ a.depthPct }}%</span></td><td class="px-3 py-2.5">{{ a.remainingLifeYears }} y</td><td class="px-3 py-2.5"><span :class="(a.safePressureKpa||0) >= (asset?.maopKpa||0) ? 'text-mint-deep' : 'text-signal-deep'">{{ (a.safePressureKpa||0) >= (asset?.maopKpa||0) ? 'Acceptable' : 'Below MAOP' }}</span></td></tr></tbody></table></div></div>
        <div v-if="comparison" class="mt-4 rounded-xl border border-ink/12 bg-bone p-4">
          <div class="flex items-center justify-between"><p class="font-display text-[18px]">Multi-run comparison</p><span class="font-mono text-[8px] uppercase tracking-[.06em] text-ink/35">{{ comparison.previous ? 'Previous run aligned' : 'First run on asset' }}</span></div>
          <template v-if="comparison.previous">
            <div class="mt-3 grid grid-cols-3 gap-2"><div class="rounded-lg bg-ink/5 p-3"><p class="font-mono text-[7px] uppercase text-ink/35">Previous max</p><p class="mt-1 font-display text-[22px]">{{ comparison.previous.maxDepthPct }}%</p></div><div class="rounded-lg bg-ink/5 p-3"><p class="font-mono text-[7px] uppercase text-ink/35">Current max</p><p class="mt-1 font-display text-[22px]">{{ comparison.current.maxDepthPct }}%</p></div><div class="rounded-lg bg-signal/10 p-3"><p class="font-mono text-[7px] uppercase text-ink/35">Change</p><p class="mt-1 font-display text-[22px] text-signal-deep">{{ (comparison.current.maxDepthPct - comparison.previous.maxDepthPct).toFixed(1) }}%</p></div></div>
            <div class="mt-3 max-h-40 overflow-auto scrollbar-thin"><table class="w-full text-left text-[10px]"><thead class="font-mono text-[7px] uppercase text-ink/35"><tr><th class="py-1">ID</th><th>Distance</th><th>Previous</th><th>Now</th><th>Delta</th></tr></thead><tbody><tr v-for="c in comparison.changes" :key="c.id" class="border-t border-ink/10"><td class="py-1.5 font-mono">{{ c.id }}</td><td>{{ (c.distanceM/1000).toFixed(2) }} km</td><td>{{ c.previousDepthPct ?? '—' }}%</td><td>{{ c.depthPct }}%</td><td :class="c.deltaPct > 0 ? 'text-signal-deep' : 'text-mint-deep'">{{ c.deltaPct != null ? `${c.deltaPct > 0 ? '+' : ''}${c.deltaPct}%` : 'new' }}</td></tr></tbody></table></div>
          </template>
          <p v-else class="mt-2 text-[11.5px] leading-relaxed text-ink/50">This is the first screened run for the asset. The next run will automatically align and calculate growth against this report.</p>
        </div>
      </div>
      <aside class="space-y-4 xl:col-span-4">
        <div class="rounded-xl border border-ink/12 bg-bone p-5"><p class="label-mono text-ink/40">Asset record</p><div class="mt-4 space-y-3 text-[12px]"><div class="flex justify-between border-b border-ink/10 pb-2"><span class="text-ink/45">Product</span><span>{{ asset?.product }}</span></div><div class="flex justify-between border-b border-ink/10 pb-2"><span class="text-ink/45">Grade</span><span>{{ asset?.grade }}</span></div><div class="flex justify-between border-b border-ink/10 pb-2"><span class="text-ink/45">Wall</span><span>{{ asset?.wallMm }} mm</span></div><div class="flex justify-between"><span class="text-ink/45">Installed</span><span>{{ asset?.installYear }}</span></div></div></div>
        <div class="rounded-xl bg-ink p-5 text-bone"><p class="flex items-center gap-2 font-mono text-[8px] uppercase tracking-[.08em] text-mint"><ShieldCheck :size="12" /> Screening complete</p><p class="mt-3 text-[12px] leading-relaxed text-bone/55">Calculations use nominal wall, measured depth and ASME B31G. A qualified engineer must review before any pressure change.</p><button class="btn btn-mint mt-4 w-full !min-h-9 !text-[10px]" @click="print">Download evidence pack</button></div>
        <div class="rounded-xl border border-ink/12 p-5"><p class="font-mono text-[8px] uppercase tracking-[.08em] text-ink/35">Recommended next step</p><p class="mt-2 font-display text-[22px]">{{ report.risk === 'critical' || report.risk === 'high' ? 'Repair before next cycle' : 'Continue monitoring' }}</p><p class="mt-2 text-[11.5px] leading-relaxed text-ink/50">Create a repair scope and invite verified contractors, or schedule a reassessment at the calculated interval.</p><NuxtLink to="/contact" class="mt-3 inline-flex items-center gap-1.5 font-mono text-[9px] uppercase tracking-[.08em] text-signal-deep">Create scope <ArrowUpRight :size="11" /></NuxtLink></div>
      </aside>
    </div>
  </div>
</template>
